{
    var jmpairs = (from member in _context.Members
        from job in _context.Jobs
        where member.Filial == filial.Id.ToString() && job.MemberId == member.Id.ToString()
        select new {Job = job, Member = member});

    var members = jmpairs.GroupBy(p => p.Member.Id).ToDictionary(g => g.First().Member, g => g.Select(i => i.Job).ToList());

    var scores = members.ToDictionary(p => p.Key.Id, p => p.Value.Count(j => j.start <= de && j.end >= db));

    var memberId = scores.OrderBy(p => p.Value).First().Key;

    return members.Keys.FirstOrDefault(m => m.Id == memberId);

