    foreach (DataColumn col in dtCloned.Columns)
    {
        var colType = map[col.ColumnName]?.Type;

        if (!string.IsNullOrEmpty(colType))
        {
            if (col.DataType != Type.GetType("System." + colType))
            {
                col.DataType = Type.GetType("System." + colType);
            }
        }


    }


    foreach (DataRow row in dataTable.Rows)
    {

        var cols = map.Columns.Where(x => x.Values != null && x.Values.Count > 0);
        foreach (var col in cols)
        {
            var colName = col.NewName != null ? col.NewName : col.Name;
            if (row.Table.Columns.Contains(colName))
            {
                var val = col.Values.FirstOrDefault(x => x.From.Equals(row[colName]));
                if (val != null)
                {
                    row[colName] = val.To;
                }

            }
        }


        var rowObj = new Dictionary<string, object>();
        foreach (DataColumn col in dtCloned.Columns)
        {
            var colName = col.ColumnName;
            if (row.Table.Columns.Contains(colName) && (colName.IndexOf("מס\"ד") == -1))
            {

                rowObj[colName] = row[colName].ToString();
            }

        }
        rowObj["Id"] = Guid.NewGuid().ToString();

